import React from 'react';
import { AlertTriangle, Clock, Flame, Droplets } from 'lucide-react';

const LeftSidebar = () => {
  const activeRisks = [
    {
      id: 1,
      type: 'Flood',
      severity: 'HIGH',
      location: '30 minutes ago',
      confidence: '94.1%',
      icon: Droplets,
      color: 'bg-orange-600'
    },
    {
      id: 2,
      type: 'Fire',
      severity: 'CRITICAL',
      location: '15 minutes ago',
      confidence: '89.0%',
      icon: Flame,
      color: 'bg-red-600'
    }
  ];

  const emergencyMessages = [
    {
      id: 1,
      priority: 'CRITICAL',
      message: 'Building collapse on 5th Avenue, multiple people trapped',
      category: 'Structure Collapse',
      time: '5 minutes ago',
      confidence: '96%'
    },
    {
      id: 2,
      priority: 'HIGH',
      message: 'Need medical supplies at evacuation center',
      category: 'Medical Request',
      time: '10 minutes ago',
      confidence: '87%'
    }
  ];

  return (
    <div className="p-4 space-y-6">
      {/* Active Disaster Zones */}
      <div className="bg-gray-700 rounded-lg p-4">
        <h3 className="text-lg font-semibold mb-4 text-white flex items-center">
          <AlertTriangle className="w-5 h-5 mr-2 text-red-500" />
          Active Disaster Zones
        </h3>
        <p className="text-sm text-gray-400 mb-4">AI-detected threats requiring immediate attention</p>
        
        <div className="space-y-3">
          {activeRisks.map((risk) => (
            <div key={risk.id} className="bg-gray-800 rounded-lg p-3 border-l-4 border-orange-500">
              <div className="flex items-center justify-between mb-2">
                <div className="flex items-center space-x-2">
                  <risk.icon className="w-4 h-4 text-orange-500" />
                  <span className="font-medium text-white">{risk.type}</span>
                </div>
                <span className={`px-2 py-1 rounded text-xs font-medium ${
                  risk.severity === 'CRITICAL' ? 'bg-red-600 text-white' : 'bg-orange-600 text-white'
                }`}>
                  {risk.severity}
                </span>
              </div>
              <div className="text-sm text-gray-400">
                <div>Detected {risk.location}</div>
                <div>Confidence: {risk.confidence}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Emergency Messages */}
      <div className="bg-gray-700 rounded-lg p-4">
        <h3 className="text-lg font-semibold mb-4 text-white">Emergency Messages</h3>
        <p className="text-sm text-gray-400 mb-4">NLP-classified priority communications</p>
        
        <div className="space-y-3">
          {emergencyMessages.map((message) => (
            <div key={message.id} className="bg-gray-800 rounded-lg p-3">
              <div className="flex items-center justify-between mb-2">
                <span className={`px-2 py-1 rounded text-xs font-medium ${
                  message.priority === 'CRITICAL' ? 'bg-red-600 text-white' : 'bg-orange-600 text-white'
                }`}>
                  {message.priority}
                </span>
                <div className="flex items-center text-xs text-gray-400">
                  <span className="mr-2">{message.confidence}</span>
                  <div className="w-8 bg-gray-600 rounded-full h-1">
                    <div 
                      className="bg-blue-500 h-1 rounded-full" 
                      style={{ width: message.confidence }}
                    ></div>
                  </div>
                </div>
              </div>
              <p className="text-sm text-white mb-2">{message.message}</p>
              <div className="flex items-center justify-between text-xs text-gray-400">
                <span>{message.category}</span>
                <span>{message.time}</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default LeftSidebar;
